screenPanels.initJs:
function(container, apiUrl, tables) {
  const tableIndex = 0; // 献立生成ログテーブル
  const logTbody = container.querySelector('#log-tbody');
  const noLogsMsg = container.querySelector('#no-logs-message');
  const detailModal = container.querySelector('#detail-modal');
  const detailContent = container.querySelector('#detail-content');
  const modalCloseBtn = container.querySelector('#modal-close-btn');
  const modalCloseBtn2 = container.querySelector('#modal-close-btn-2');
  const retryBtn = container.querySelector('#retry-button');
  const searchInput = container.querySelector('[data-testid="search-input"]');
  const statusFilter = container.querySelector('[data-testid="status-filter"]');
  const userFilter = container.querySelector('[data-testid="user-filter"]');
  const searchBtn = container.querySelector('[data-testid="search-button"]');
  const exportBtn = container.querySelector('[data-testid="export-button"]');

  const kpiTodayCount = container.querySelector('[data-testid="kpi-today-count"]');
  const kpiSuccessCount = container.querySelector('[data-testid="kpi-success-count"]');
  const kpiErrorCount = container.querySelector('[data-testid="kpi-error-count"]');
  const kpiProcessingCount = container.querySelector('[data-testid="kpi-processing-count"]');

  let allLogs = [];
  let currentDetailLog = null;

  // ============ ユーティリティ ============
  const formatDateTime = (dateStr) => {
    if (!dateStr) return '—';
    const d = new Date(dateStr);
    return d.toLocaleString('ja-JP', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit' });
  };

  const getStatusBadge = (status) => {
    const statusMap = {
      success: { label: '成功', color: '#10b981' },
      error: { label: '失敗', color: '#ef4444' },
      processing: { label: '処理中', color: '#f59e0b' }
    };
    const s = statusMap[status] || { label: status, color: '#8b7d6b' };
    return `<span style="display: inline-block; padding: 2px 8px; border-radius: 3px; background: ${s.color}20; color: ${s.color}; font-size: 12px; font-weight: 500;">${s.label}</span>`;
  };

  // ============ ログ一覧の描画 ============
  const renderLogs = (logs) => {
    logTbody.innerHTML = '';
    if (logs.length === 0) {
      noLogsMsg.style.display = 'block';
      return;
    }
    noLogsMsg.style.display = 'none';

    logs.forEach((log) => {
      const tr = document.createElement('tr');
      tr.style.borderBottom = '1px solid var(--border)';
      tr.style.backgroundColor = 'var(--bg-main)';
      tr.style.cursor = 'pointer';
      tr.dataset.id = log.id;
      tr.innerHTML = `
        <td style="padding: 8px; color: var(--text);">${log.logId || '—'}</td>
        <td style="padding: 8px; color: var(--text);">${log.userName || '—'}</td>
        <td style="padding: 8px; color: var(--text);">${log.familyMemberName || '—'}</td>
        <td style="padding: 8px; color: var(--text); font-size: 12px;">${formatDateTime(log.executedAt)}</td>
        <td style="padding: 8px; color: var(--text); font-size: 12px;">${formatDateTime(log.completedAt)}</td>
        <td style="padding: 8px; text-align: center;">${getStatusBadge(log.status)}</td>
        <td style="padding: 8px; text-align: center; color: var(--text);">${log.generatedCount || 0}</td>
        <td style="padding: 8px; color: ${log.errorMessage ? '#ef4444' : 'var(--text-muted)'}; font-size: 12px; max-width: 200px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">
          ${log.errorMessage || '—'}
        </td>
        <td style="padding: 8px; text-align: center;">
          <button class="detail-btn" style="background: transparent; border: 1px solid var(--border); color: var(--text); padding: 4px 8px; border-radius: 3px; cursor: pointer; font-size: 12px;">
            詳細
          </button>
        </td>
      `;
      tr.addEventListener('click', (e) => {
        if (e.target.classList.contains('detail-btn')) {
          showDetail(log);
        }
      });
      logTbody.appendChild(tr);
    });
  };

  // ============ KPI 更新 ============
  const updateKpis = (logs) => {
    const today = new Date().toDateString();
    const todayLogs = logs.filter(l => new Date(l.executedAt).toDateString() === today);
    const successLogs = logs.filter(l => l.status === 'success');
    const errorLogs = logs.filter(l => l.status === 'error');
    const processingLogs = logs.filter(l => l.status === 'processing');

    kpiTodayCount.textContent = todayLogs.length;
    kpiSuccessCount.textContent = successLogs.length;
    kpiErrorCount.textContent = errorLogs.length;
    kpiProcessingCount.textContent = processingLogs.length;
  };

  // ============ 詳細表示 ============
  const showDetail = (log) => {
    currentDetailLog = log;
    detailContent.innerHTML = `
      <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-bottom: 16px;">
        <div>
          <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">ログID</div>
          <div style="font-weight: 500;">${log.logId || '—'}</div>
        </div>
        <div>
          <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">ユーザー名</div>
          <div style="font-weight: 500;">${log.userName || '—'}</div>
        </div>
        <div>
          <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">家族成員名</div>
          <div style="font-weight: 500;">${log.familyMemberName || '—'}</div>
        </div>
        <div>
          <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">ステータス</div>
          <div>${getStatusBadge(log.status)}</div>
        </div>
        <div>
          <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">生成実行日時</div>
          <div style="font-weight: 500; font-size: 12px;">${formatDateTime(log.executedAt)}</div>
        </div>
        <div>
          <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">生成完了日時</div>
          <div style="font-weight: 500; font-size: 12px;">${formatDateTime(log.completedAt)}</div>
        </div>
        <div>
          <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">生成献立数</div>
          <div style="font-weight: 500;">${log.generatedCount || 0}</div>
        </div>
        <div>
          <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">処理時間</div>
          <div style="font-weight: 500;">${log.processingTime || '—'}</div>
        </div>
      </div>
      ${log.errorMessage ? `
        <div style="background: #ef444420; border: 1px solid #ef4444; border-radius: 4px; padding: 8px; margin-bottom: 12px;">
          <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">エラー内容</div>
          <div style="color: #ef4444; font-size: 12px; word-break: break-word;">${log.errorMessage}</div>
        </div>
      ` : ''}
      ${log.notes ? `
        <div style="background: var(--bg-main); border: 1px solid var(--border); border-radius: 4px; padding: 8px;">
          <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">備考</div>
          <div style="font-size: 12px; color: var(--text); word-break: break-word;">${log.notes}</div>
        </div>
      ` : ''}
    `;

    // 失敗ステータスの場合のみ「再実行」ボタンを表示
    retryBtn.style.display = log.status === 'error' ? 'block' : 'none';

    detailModal.style.display = 'flex';
  };

  const closeDetail = () => {
    detailModal.style.display = 'none';
    currentDetailLog = null;
  };

  // ============ フィルタリング ============
  const applyFilters = () => {
    const searchTerm = searchInput.value.toLowerCase();
    const statusVal = statusFilter.value;
    const userVal = userFilter.value;

    const filtered = allLogs.filter(log => {
      const matchSearch = !searchTerm || 
        (log.logId && log.logId.toLowerCase().includes(searchTerm)) ||
        (log.userName && log.userName.toLowerCase().includes(searchTerm));
      const matchStatus = !statusVal || log.status === statusVal;
      const matchUser = !userVal || log.userId === userVal;
      return matchSearch && matchStatus && matchUser;
    });

    renderLogs(filtered);
  };

  // ============ CSVエクスポート ============
  const exportCsv = async () => {
    const logs = await window.aivicApi.list(tableIndex);
    if (!logs) return;

    const headers = ['ログID', 'ユーザー名', '家族成員名', '生成実行日時', '生成完了日時', 'ステータス', '献立数', 'エラー内容'];
    const rows = logs.map(log => [
      log.logId || '',
      log.userName || '',
      log.familyMemberName || '',
      formatDateTime(log.executedAt),
      formatDateTime(log.completedAt),
      log.status || '',
      log.generatedCount || '',
      log.errorMessage || ''
    ]);

    const csv = [headers, ...rows]
      .map(row => row.map(cell => {
        const str = String(cell);
        return str.includes(',') || str.includes('"') || str.includes('\n') 
          ? `"${str.replace(/"/g, '""')}"` 
          : str;
      }).join(','))
      .join('\n');

    const bom = '\uFEFF';
    const blob = new Blob([bom + csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `献立生成ログ_${new Date().toISOString().slice(0, 10)}.csv`;
    link.click();
  };

  // ============ 再実行 ============
  const retryGeneration = async () => {
    if (!currentDetailLog) return;

    // 再実行処理（API呼び出し）
    const result = await window.aivicApi.update(tableIndex, currentDetailLog.id, {
      status: 'processing',
      retryCount: (currentDetailLog.retryCount || 0) + 1
    });

    if (result) {
      alert('献立生成を再実行しました');
      closeDetail();
      loadLogs();
    }
  };

  // ============ ログ読み込み ============
  const loadLogs = async () => {
    const logs = await window.aivicApi.list(tableIndex);
    if (!logs) return;

    allLogs = logs;
    updateKpis(allLogs);
    renderLogs(allLogs);
  };

  // ============ イベントリスナー ============
  searchBtn.addEventListener('click', applyFilters);
  searchInput.addEventListener('keyup', (e) => {
    if (e.key === 'Enter') applyFilters();
  });
  statusFilter.addEventListener('change', applyFilters);
  userFilter.addEventListener('change', applyFilters);
  exportBtn.addEventListener('click', exportCsv);

  modalCloseBtn.addEventListener('click', closeDetail);
  modalCloseBtn2.addEventListener('click', closeDetail);
  retryBtn.addEventListener('click', retryGeneration);

  // Escキーでモーダルを閉じる
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && detailModal.style.display === 'flex') {
      closeDetail();
    }
  });

  // overlay背景クリックで閉じる
  detailModal.addEventListener('click', (e) => {
    if (e.target === detailModal) {
      closeDetail();
    }
  });

  // ============ 初期化 ============
  loadLogs();

  // リアルタイム更新（5秒ごと）
  setInterval(loadLogs, 5000);
}

function(container, apiUrl, tables) {
  const algorithmSelect = container.querySelector('[data-testid="algorithm-select"]');
  const nutritionSlider = container.querySelector('[data-testid="nutrition-slider"]');
  const nutritionValue = container.querySelector('[data-testid="nutrition-value"]');
  const costSlider = container.querySelector('[data-testid="cost-slider"]');
  const costValue = container.querySelector('[data-testid="cost-value"]');
  const timeSlider = container.querySelector('[data-testid="time-slider"]');
  const timeValue = container.querySelector('[data-testid="time-value"]');
  const preferenceSlider = container.querySelector('[data-testid="preference-slider"]');
  const preferenceValue = container.querySelector('[data-testid="preference-value"]');
  const allergySync = container.querySelector('[data-testid="allergy-sync"]');
  const restrictionSync = container.querySelector('[data-testid="restriction-sync"]');
  const historyToggle = container.querySelector('[data-testid="history-toggle"]');
  const learningPeriod = container.querySelector('[data-testid="learning-period"]');
  const previewButton = container.querySelector('[data-testid="preview-button"]');
  const updateButton = container.querySelector('[data-testid="update-button"]');
  const allergyLink = container.querySelector('[data-testid="allergy-link"]');
  const conditionLink = container.querySelector('[data-testid="condition-link"]');
  const previewContent = container.querySelector('[data-testid="preview-content"]');
  const excludedItems = container.querySelector('[data-testid="excluded-items"]');
  const recommendedItems = container.querySelector('[data-testid="recommended-items"]');
  const lastUpdate = container.querySelector('[data-testid="last-update"]');
  const confirmModal = container.querySelector('[data-testid="confirm-modal"]');
  const confirmCancel = container.querySelector('[data-testid="confirm-cancel"]');
  const confirmOk = container.querySelector('[data-testid="confirm-ok"]');
  const successModal = container.querySelector('[data-testid="success-modal"]');
  const successClose = container.querySelector('[data-testid="success-close"]');

  // スライダー値の表示更新
  const updateSliderDisplay = () => {
    nutritionValue.textContent = nutritionSlider.value + '%';
    costValue.textContent = costSlider.value + '%';
    timeValue.textContent = timeSlider.value + '%';
    preferenceValue.textContent = preferenceSlider.value + '%';
  };

  nutritionSlider.addEventListener('input', updateSliderDisplay);
  costSlider.addEventListener('input', updateSliderDisplay);
  timeSlider.addEventListener('input', updateSliderDisplay);
  preferenceSlider.addEventListener('input', updateSliderDisplay);

  // プレビューボタン
  previewButton.addEventListener('click', async () => {
    const algorithm = algorithmSelect.value;
    if (!algorithm) {
      previewContent.textContent = 'アルゴリズムを選択してください';
      return;
    }

    const params = {
      algorithm,
      nutrition: parseInt(nutritionSlider.value),
      cost: parseInt(costSlider.value),
      time: parseInt(timeSlider.value),
      preference: parseInt(preferenceSlider.value),
      allergySync: allergySync.checked,
      restrictionSync: restrictionSync.checked,
      useHistory: historyToggle.checked,
      learningPeriod: parseInt(learningPeriod.value)
    };

    previewContent.innerHTML = `
      <div style="font-size: 12px; line-height: 1.6;">
        <strong>アルゴリズム:</strong> ${algorithm}<br>
        <strong>優先度:</strong> 栄養${params.nutrition}% / コスト${params.cost}% / 時間${params.time}% / 嗜好${params.preference}%<br>
        <strong>同期:</strong> アレルギー${params.allergySync ? '有効' : '無効'} / 制限${params.restrictionSync ? '有効' : '無効'}<br>
        <strong>学習期間:</strong> ${params.learningPeriod}日<br>
        <strong>評価データ:</strong> ${params.useHistory ? '活用' : '未使用'}
      </div>
    `;

    // 食材リストを読み込み
    loadFoodLists(params);
  });

  // 食材リスト読み込み
  const loadFoodLists = async (params) => {
    // ダミーデータ（実際はAPIから取得）
    const excluded = ['ピーナッツ', 'エビ', 'そば', 'クルミ', 'ゴマ'];
    const recommended = ['鶏肉', 'ブロッコリー', '玄米', 'サーモン', 'ニンジン', 'トマト'];

    excludedItems.innerHTML = excluded.map(item => 
      `<div style="display: inline-block; background: var(--primary); color: #fff; padding: 4px 8px; border-radius: 3px; margin: 2px; font-size: 11px;">${item}</div>`
    ).join('');

    recommendedItems.innerHTML = recommended.map(item => 
      `<div style="display: inline-block; background: var(--bg-sidebar); color: var(--text); padding: 4px 8px; border-radius: 3px; margin: 2px; font-size: 11px; border: 1px solid var(--border);">${item}</div>`
    ).join('');
  };

  // 更新ボタン
  updateButton.addEventListener('click', () => {
    if (!algorithmSelect.value) {
      alert('アルゴリズムを選択してください');
      return;
    }
    confirmModal.style.display = 'flex';
  });

  // 確認モーダル: キャンセル
  confirmCancel.addEventListener('click', () => {
    confirmModal.style.display = 'none';
  });

  // 確認モーダル: 実行
  confirmOk.addEventListener('click', async () => {
    confirmModal.style.display = 'none';

    const params = {
      algorithm: algorithmSelect.value,
      nutrition: parseInt(nutritionSlider.value),
      cost: parseInt(costSlider.value),
      time: parseInt(timeSlider.value),
      preference: parseInt(preferenceSlider.value),
      allergySync: allergySync.checked,
      restrictionSync: restrictionSync.checked,
      useHistory: historyToggle.checked,
      learningPeriod: parseInt(learningPeriod.value),
      updatedAt: new Date().toISOString()
    };

    // API呼び出し（テーブルがあれば）
    if (tables && tables.length > 0) {
      const saved = await window.aivicApi.save(0, params);
      if (saved) {
        lastUpdate.textContent = new Date().toLocaleString('ja-JP');
        successModal.style.display = 'flex';
      }
    } else {
      lastUpdate.textContent = new Date().toLocaleString('ja-JP');
      successModal.style.display = 'flex';
    }
  };

  // 成功モーダル: 閉じる
  successClose.addEventListener('click', () => {
    successModal.style.display = 'none';
  });

  // 詳細設定リンク
  allergyLink.addEventListener('click', () => {
    window.showScreen('scr-1783678285918');
  });

  conditionLink.addEventListener('click', () => {
    window.showScreen('scr-1783678463634');
  });

  // Escキーでモーダルを閉じる
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
      confirmModal.style.display = 'none';
      successModal.style.display = 'none';
    }
  });

  // overlay背景クリックで閉じる
  confirmModal.addEventListener('click', (e) => {
    if (e.target === confirmModal) {
      confirmModal.style.display = 'none';
    }
  });

  successModal.addEventListener('click', (e) => {
    if (e.target === successModal) {
      successModal.style.display = 'none';
    }
  });

  // 初期表示
  updateSliderDisplay();
}

function(container, apiUrl, tables) {
  const form = container.querySelector('#priority-form');
  const previewContent = container.querySelector('#preview-content');
  const saveBtn = container.querySelector('#save-btn');
  const resetBtn = container.querySelector('#reset-btn');

  // スライダー値表示の更新
  const sliders = {
    'allergy-priority': 'allergy-value',
    'restriction-priority': 'restriction-value',
    'rating-weight': 'rating-value',
    'nutrition-priority': 'nutrition-value'
  };

  Object.entries(sliders).forEach(([sliderId, valueId]) => {
    const slider = container.querySelector(`#${sliderId}`);
    const valueSpan = container.querySelector(`#${valueId}`);
    if (slider && valueSpan) {
      slider.addEventListener('input', (e) => {
        valueSpan.textContent = e.target.value + '%';
        updatePreview();
      });
    }
  });

  // フォーム入力時のプレビュー更新
  form.addEventListener('change', updatePreview);
  form.addEventListener('input', updatePreview);

  // プレビュー更新関数
  function updatePreview() {
    const userSelect = container.querySelector('#user-select');
    const familySelect = container.querySelector('#family-select');
    const allergyPriority = container.querySelector('#allergy-priority').value;
    const restrictionPriority = container.querySelector('#restriction-priority').value;
    const ratingWeight = container.querySelector('#rating-weight').value;
    const nutritionPriority = container.querySelector('#nutrition-priority').value;
    const budgetLimit = container.querySelector('#budget-limit').value;
    const cookingTimeLimit = container.querySelector('#cooking-time-limit').value;
    const excludedIngredientsText = container.querySelector('#excluded-ingredients').value;
    const generationFrequency = container.querySelector('input[name="generationFrequency"]:checked').value;

    // 選択された好み
    const preferences = Array.from(container.querySelectorAll('input[name="preference"]:checked'))
      .map(cb => {
        const labels = { fish: '魚類', meat: '肉類', vegetable: '野菜', soy: '大豆製品', grain: '穀類', dairy: '乳製品' };
        return labels[cb.value];
      });

    // 除外食材をパース
    const excludedIngredients = excludedIngredientsText
      .split(',')
      .map(s => s.trim())
      .filter(s => s.length > 0);

    const previewObj = {
      user: userSelect.value ? userSelect.options[userSelect.selectedIndex].text : '未選択',
      familyMember: familySelect.value ? familySelect.options[familySelect.selectedIndex].text : '全員',
      priorities: {
        allergy: parseInt(allergyPriority),
        restriction: parseInt(restrictionPriority),
        rating: parseInt(ratingWeight),
        nutrition: parseInt(nutritionPriority)
      },
      constraints: {
        budgetPerMeal: parseInt(budgetLimit),
        cookingTimeLimit: parseInt(cookingTimeLimit)
      },
      preferences: preferences,
      excludedIngredients: excludedIngredients,
      generationFrequency: generationFrequency
    };

    previewContent.textContent = JSON.stringify(previewObj, null, 2);
  }

  // 保存ボタン
  saveBtn.addEventListener('click', async () => {
    const formData = new FormData(form);
    const data = {
      userId: formData.get('userId'),
      familyMemberId: formData.get('familyMemberId'),
      allergyPriority: parseInt(formData.get('allergyPriority')),
      restrictionPriority: parseInt(formData.get('restrictionPriority')),
      ratingWeight: parseInt(formData.get('ratingWeight')),
      nutritionPriority: parseInt(formData.get('nutritionPriority')),
      budgetLimit: parseInt(formData.get('budgetLimit')),
      cookingTimeLimit: parseInt(formData.get('cookingTimeLimit')),
      preferences: Array.from(container.querySelectorAll('input[name="preference"]:checked')).map(cb => cb.value),
      excludedIngredients: formData.get('excludedIngredients').split(',').map(s => s.trim()).filter(s => s),
      generationFrequency: formData.get('generationFrequency')
    };

    if (!data.userId) {
      alert('ユーザーを選択してください');
      return;
    }

    const saved = await window.aivicApi.save(0, data);
    if (saved) {
      alert('優先条件を保存しました');
    }
  });

  // リセットボタン
  resetBtn.addEventListener('click', () => {
    if (confirm('設定をリセットしますか？')) {
      form.reset();
      container.querySelector('#allergy-priority').value = 90;
      container.querySelector('#restriction-priority').value = 85;
      container.querySelector('#rating-weight').value = 70;
      container.querySelector('#nutrition-priority').value = 75;
      container.querySelector('#budget-limit').value = 800;
      container.querySelector('#cooking-time-limit').value = 45;
      container.querySelector('input[name="generationFrequency"][value="daily"]').checked = true;
      container.querySelector('input[name="preference"][value="vegetable"]').checked = true;
      container.querySelector('input[name="preference"][value="soy"]').checked = true;
      container.querySelector('input[name="preference"][value="grain"]').checked = true;
      updatePreview();
    }
  });

  // 関連画面へのナビゲーション
  container.querySelector('[data-testid="allergy-management-btn"]').addEventListener('click', () => {
    window.showScreen('scr-1783678285918');
  });

  container.querySelector('[data-testid="generation-log-btn"]').addEventListener('click', () => {
    window.showScreen('scr-1783678313897');
  });

  container.querySelector('[data-testid="improvement-proposal-btn"]').addEventListener('click', () => {
    window.showScreen('scr-1783678782157');
  });

  // 初期プレビュー表示
  updatePreview();
}

function(container, apiUrl, tables) {
  const sourcesList = container.querySelector('#sources-list');
  const detailPanel = container.querySelector('#detail-panel');
  const sourceModal = container.querySelector('#source-modal');
  const deleteModal = container.querySelector('#delete-modal');
  const addSourceBtn = container.querySelector('[data-testid="add-source-btn"]');
  const modalCancelBtn = container.querySelector('[data-testid="modal-cancel-btn"]');
  const modalSaveBtn = container.querySelector('[data-testid="modal-save-btn"]');
  const deleteCancelBtn = container.querySelector('[data-testid="delete-cancel-btn"]');
  const deleteConfirmBtn = container.querySelector('[data-testid="delete-confirm-btn"]');

  let sources = [];
  let selectedSourceId = null;
  let editingSourceId = null;

  // データソース一覧を取得・表示
  async function loadSources() {
    sources = await window.aivicApi.list(0) || [];
    renderSourcesList();
  }

  // ソース一覧をレンダリング
  function renderSourcesList() {
    sourcesList.innerHTML = sources.map(src => `
      <div data-id="${src.id}" class="source-item" style="padding: 10px 12px; border-bottom: 1px solid var(--border); cursor: pointer; transition: background 0.2s; background: ${selectedSourceId === src.id ? 'var(--bg-main)' : 'transparent'};" data-testid="source-item-${src.id}">
        <div style="font-size: 13px; font-weight: 500; color: var(--text);">${src.name || 'Unnamed'}</div>
        <div style="font-size: 11px; color: var(--text-muted); margin-top: 2px;">
          <span style="display: inline-block; padding: 2px 6px; background: ${src.status === 'connected' ? '#dcfce7' : '#fee2e2'}; color: ${src.status === 'connected' ? '#166534' : '#991b1b'}; border-radius: 3px;">
            ${src.status === 'connected' ? '✓ 接続中' : '✗ 未接続'}
          </span>
        </div>
      </div>
    `).join('');

    // クリックイベント
    sourcesList.querySelectorAll('.source-item').forEach(item => {
      item.addEventListener('click', () => {
        selectedSourceId = item.dataset.id;
        renderSourcesList();
        showSourceDetail(selectedSourceId);
      });
    });
  }

  // ソース詳細を表示
  function showSourceDetail(sourceId) {
    const source = sources.find(s => s.id === sourceId);
    if (!source) return;

    const lastSync = source.lastSyncTime ? new Date(source.lastSyncTime).toLocaleString('ja-JP') : '未実行';
    const syncStatus = source.syncStatus || 'idle';

    detailPanel.innerHTML = `
      <div style="padding: 16px; border-bottom: 1px solid var(--border); display: flex; justify-content: space-between; align-items: center;">
        <h3 style="font-size: 14px; font-weight: 600; margin: 0;">${source.name}</h3>
        <div style="display: flex; gap: 6px;">
          <button data-testid="edit-source-btn" class="action-btn secondary" style="padding: 6px 12px; font-size: 12px; background: transparent; border: 1px solid var(--border); color: var(--text);">編集</button>
          <button data-testid="delete-source-btn" class="action-btn secondary" style="padding: 6px 12px; font-size: 12px; background: transparent; border: 1px solid var(--border); color: var(--text);">削除</button>
        </div>
      </div>

      <div style="flex: 1; overflow-y: auto; padding: 16px;">
        <!-- 接続状態セクション -->
        <div style="margin-bottom: 20px;">
          <h4 style="font-size: 12px; font-weight: 600; color: var(--text-muted); margin: 0 0 8px 0; text-transform: uppercase;">接続状態</h4>
          <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 12px;">
            <div style="background: var(--bg-main); padding: 12px; border-radius: 4px; border: 1px solid var(--border);">
              <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">ステータス</div>
              <div style="font-size: 14px; font-weight: 600; color: ${source.status === 'connected' ? '#16a34a' : '#dc2626'};">
                ${source.status === 'connected' ? '✓ 接続中' : '✗ 未接続'}
              </div>
            </div>
            <div style="background: var(--bg-main); padding: 12px; border-radius: 4px; border: 1px solid var(--border);">
              <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">最終同期</div>
              <div style="font-size: 12px; color: var(--text);">${lastSync}</div>
            </div>
          </div>
        </div>

        <!-- 同期セクション -->
        <div style="margin-bottom: 20px;">
          <h4 style="font-size: 12px; font-weight: 600; color: var(--text-muted); margin: 0 0 8px 0; text-transform: uppercase;">同期管理</h4>
          <div style="display: flex; gap: 8px; margin-bottom: 12px;">
            <button data-testid="sync-now-btn" class="action-btn" style="padding: 8px 12px; font-size: 12px; flex: 1;">今すぐ同期</button>
            <button data-testid="sync-schedule-btn" class="action-btn secondary" style="padding: 8px 12px; font-size: 12px; flex: 1; background: transparent; border: 1px solid var(--border); color: var(--text);">スケジュール設定</button>
          </div>
          <div style="background: var(--bg-main); padding: 10px; border-radius: 4px; border: 1px solid var(--border); font-size: 12px; color: var(--text-muted);">
            <div>スケジュール: ${source.syncSchedule || '未設定'}</div>
            <div style="margin-top: 4px;">同期ステータス: <span style="color: var(--text);">${syncStatus === 'syncing' ? '同期中...' : syncStatus === 'success' ? '成功' : '待機中'}</span></div>
          </div>
        </div>

        <!-- 認証情報セクション -->
        <div style="margin-bottom: 20px;">
          <h4 style="font-size: 12px; font-weight: 600; color: var(--text-muted); margin: 0 0 8px 0; text-transform: uppercase;">認証情報</h4>
          <div style="background: var(--bg-main); padding: 12px; border-radius: 4px; border: 1px solid var(--border);">
            <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">タイプ</div>
            <div style="font-size: 13px; color: var(--text); margin-bottom: 12px;">${source.sourceType || 'API'}</div>
            <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">エンドポイント</div>
            <div style="font-size: 12px; color: var(--text); word-break: break-all; margin-bottom: 12px; font-family: monospace;">${source.endpoint || '-'}</div>
            <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">API キー</div>
            <div style="font-size: 12px; color: var(--text); font-family: monospace;">••••••••</div>
          </div>
        </div>

        <!-- データマッピングセクション -->
        <div style="margin-bottom: 20px;">
          <h4 style="font-size: 12px; font-weight: 600; color: var(--text-muted); margin: 0 0 8px 0; text-transform: uppercase;">データマッピング</h4>
          <div style="background: var(--bg-main); padding: 12px; border-radius: 4px; border: 1px solid var(--border);">
            <table data-testid="mapping-table" style="width: 100%; font-size: 12px; border-collapse: collapse;">
              <thead>
                <tr style="border-bottom: 1px solid var(--border);">
                  <th style="text-align: left; padding: 6px 0; color: var(--text); font-weight: 600;">外部フィールド</th>
                  <th style="text-align: left; padding: 6px 0; color: var(--text); font-weight: 600;">内部フィールド</th>
                </tr>
              </thead>
              <tbody>
                ${(source.mappings || []).map(m => `
                  <tr style="border-bottom: 1px solid var(--border);">
                    <td style="padding: 6px 0; color: var(--text);">${m.external}</td>
                    <td style="padding: 6px 0; color: var(--text);">${m.internal}</td>
                  </tr>
                `).join('') || '<tr><td colspan="2" style="padding: 6px 0; color: var(--text-muted);">マッピング未設定</td></tr>'}
              </tbody>
            </table>
            <button data-testid="edit-mapping-btn" class="action-btn secondary" style="margin-top: 8px; padding: 6px 12px; font-size: 12px; background: transparent; border: 1px solid var(--border); color: var(--text); width: 100%;">マッピング編集</button>
          </div>
        </div>

        <!-- フィルタ条件セクション -->
        <div>
          <h4 style="font-size: 12px; font-weight: 600; color: var(--text-muted); margin: 0 0 8px 0; text-transform: uppercase;">フィルタ条件</h4>
          <div style="background: var(--bg-main); padding: 12px; border-radius: 4px; border: 1px solid var(--border);">
            <div style="font-size: 12px; color: var(--text-muted); margin-bottom: 8px;">
              ${source.filters && source.filters.length > 0 ? source.filters.map(f => `<div>• ${f}</div>`).join('') : '<div>フィルタ条件なし</div>'}
            </div>
            <button data-testid="edit-filter-btn" class="action-btn secondary" style="padding: 6px 12px; font-size: 12px; background: transparent; border: 1px solid var(--border); color: var(--text); width: 100%;">フィルタ編集</button>
          </div>
        </div>
      </div>
    `;

    // イベントリスナー
    detailPanel.querySelector('[data-testid="edit-source-btn"]').addEventListener('click', () => openEditModal(sourceId));
    detailPanel.querySelector('[data-testid="delete-source-btn"]').addEventListener('click', () => openDeleteModal(sourceId));
    detailPanel.querySelector('[data-testid="sync-now-btn"]').addEventListener('click', () => syncNow(sourceId));
    detailPanel.querySelector('[data-testid="sync-schedule-btn"]').addEventListener('click', () => openScheduleModal(sourceId));
    detailPanel.querySelector('[data-testid="edit-mapping-btn"]').addEventListener('click', () => openMappingModal(sourceId));
    detailPanel.querySelector('[data-testid="edit-filter-btn"]').addEventListener('click', () => openFilterModal(sourceId));
  }

  // モーダル: 新規追加
  function openAddModal() {
    editingSourceId = null;
    container.querySelector('#modal-title').textContent = '新規データソース追加';
    container.querySelector('[data-testid="source-name-input"]').value = '';
    container.querySelector('[data-testid="source-type-select"]').value = '';
    container.querySelector('[data-testid="source-endpoint-input"]').value = '';
    container.querySelector('[data-testid="source-apikey-input"]').value = '';
    sourceModal.style.display = 'flex';
  }

  // モーダル: 編集
  function openEditModal(sourceId) {
    const source = sources.find(s => s.id === sourceId);
    if (!source) return;
    editingSourceId = sourceId;
    container.querySelector('#modal-title').textContent = 'データソース編集';
    container.querySelector('[data-testid="source-name-input"]').value = source.name || '';
    container.querySelector('[data-testid="source-type-select"]').value = source.sourceType || '';
    container.querySelector('[data-testid="source-endpoint-input"]').value = source.endpoint || '';
    container.querySelector('[data-testid="source-apikey-input"]').value = '';
    sourceModal.style.display = 'flex';
  }

  // モーダル: 削除確認
  function openDeleteModal(sourceId) {
    editingSourceId = sourceId;
    deleteModal.style.display = 'flex';
  }

  // モーダル: スケジュール設定（簡易版）
  function openScheduleModal(sourceId) {
    const schedule = prompt('同期スケジュール（例: 毎日 09:00）を入力してください:');
    if (schedule !== null && editingSourceId === null) {
      const source = sources.find(s => s.id === sourceId);
      if (source) {
        source.syncSchedule = schedule;
        window.aivicApi.update(0, sourceId, { syncSchedule: schedule });
        showSourceDetail(sourceId);
      }
    }
  }

  // モーダル: データマッピング編集（簡易版）
  function openMappingModal(sourceId) {
    alert('データマッピング編集画面は別途実装予定です');
  }

  // モーダル: フィルタ条件編集（簡易版）
  function openFilterModal(sourceId) {
    alert('フィルタ条件編集画面は別途実装予定です');
  }

  // 今すぐ同期
  async function syncNow(sourceId) {
    const source = sources.find(s => s.id === sourceId);
    if (!source) return;
    source.syncStatus = 'syncing';
    showSourceDetail(sourceId);

    // 3秒後に完了
    setTimeout(() => {
      source.syncStatus = 'success';
      source.lastSyncTime = new Date().toISOString();
      window.aivicApi.update(0, sourceId, { syncStatus: 'success', lastSyncTime: source.lastSyncTime });
      showSourceDetail(sourceId);
    }, 3000);
  }

  // モーダルを閉じる
  function closeSourceModal() {
    sourceModal.style.display = 'none';
  }

  function closeDeleteModal() {
    deleteModal.style.display = 'none';
  }

  // 保存処理
  async function saveSource() {
    const name = container.querySelector('[data-testid="source-name-input"]').value.trim();
    const sourceType = container.querySelector('[data-testid="source-type-select"]').value;
    const endpoint = container.querySelector('[data-testid="source-endpoint-input"]').value.trim();
    const apiKey = container.querySelector('[data-testid="source-apikey-input"]').value.trim();

    if (!name || !sourceType || !endpoint) {
      alert('必須項目を入力してください');
      return;
    }

    const data = {
      name,
      sourceType,
      endpoint,
      apiKey: apiKey || undefined,
      status: 'connected',
      syncStatus: 'idle',
      lastSyncTime: null,
      mappings: [],
      filters: []
    };

    if (editingSourceId) {
      await window.aivicApi.update(0, editingSourceId, data);
    } else {
      await window.aivicApi.save(0, data);
    }

    closeSourceModal();
    await loadSources();
  }

  // 削除処理
  async function deleteSource() {
    if (editingSourceId) {
      await window.aivicApi.delete(0, editingSourceId);
      closeDeleteModal();
      selectedSourceId = null;
      await loadSources();
      detailPanel.innerHTML = '<div style="padding: 24px; text-align: center; color: var(--text-muted);">ソースを選択してください</div>';
    }
  }

  // イベントリスナー登録
  addSourceBtn.addEventListener('click', openAddModal);
  modalCancelBtn.addEventListener('click', closeSourceModal);
  modalSaveBtn.addEventListener('click', saveSource);
  deleteCancelBtn.addEventListener('click', closeDeleteModal);
  deleteConfirmBtn.addEventListener('click', deleteSource);

  // Esc キーでモーダルを閉じる
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
      closeSourceModal();
      closeDeleteModal();
    }
  });

  // overlay クリックで閉じる
  sourceModal.addEventListener('click', (e) => {
    if (e.target === sourceModal) closeSourceModal();
  });
  deleteModal.addEventListener('click', (e) => {
    if (e.target === deleteModal) closeDeleteModal();
  });

  // 初期化
  loadSources();
}
